				if (unlikely(page_count <  max_pages))
					bytes = page_count << PAGE_CACHE_SHIFT;
				result = ll_direct_IO_26_seg(env, io, rw, inode,
							     file->f_mapping,
							     bytes, file_offset,
							     pages, page_count);
				ll_free_user_pages(pages, max_pages, rw==READ);
